NOVELTY = r'''
<section id="perspectives" class="research-section"><div class="wrap">
  <p class="overline">The shift / Make the reasoning inspectable</p>
  <div class="research-heading reveal"><h2>Separate the questions.<br><span>Connect the evidence.</span></h2><p>The bad result is easy to see. The decision that caused it is harder to find. AgentReroute brings three perspectives to that question—and learns from what happens after a repair.</p></div>
  <div class="perspective-comparison reveal">
    <article class="approach baseline-approach"><div class="approach-label"><span class="engine-mark">Rx</span><div><h3>AgentRx</h3><span>A joint judgment</span></div></div><div class="trace-strip">The full conversation + its constraints</div><div class="diagram-join" aria-hidden="true">↓</div><div class="joint-judge"><span class="tiny-label">ONE FINAL JUDGE</span><strong>“Where did this go wrong?”</strong><p>Weigh the trace and violation log together.</p></div><div class="diagram-join" aria-hidden="true">↓</div><div class="decision-card">Critical step + explanation</div><p class="approach-note">The final attribution comes from one joint LLM assessment of the evidence.</p></article>
    <article class="approach multi-approach"><div class="approach-label"><span class="engine-mark">↗</span><div><h3>AgentReroute</h3><span>Three views. A decision that can learn.</span></div></div><div class="trace-strip">The same conversation, examined through three lenses</div><div class="lens-fan" aria-hidden="true"><i></i><i></i><i></i></div><div class="lens-cards"><div class="lens-card intent"><span>01 / INTENT</span><strong>Was this the right plan?</strong><small>Cancel order ≠ catalog lookup.</small></div><div class="lens-card tools"><span>02 / EXECUTION</span><strong>Did the tools work?</strong><small>The lookup can be valid.</small></div><div class="lens-card context"><span>03 / HANDOFF</span><strong>Did the facts survive?</strong><small>The order ID can be intact.</small></div></div><div class="diagram-join" aria-hidden="true">↓</div><div class="decision-card"><strong>The routing decision is the candidate.</strong><span>Combine the evidence → rank possible faults</span></div><div class="feedback-loop"><span aria-hidden="true">↻</span><p>Try a repair. Verify the outcome.<br><strong>Feed the result back into the ranking policy.</strong></p></div></article>
  </div><p class="research-note">The example illustrates how the evidence can point upstream. Both systems check constraints; AgentReroute separates the evidence by perspective and adds a policy that can learn from recovery feedback.</p>
</div></section>
'''


def chart(metric):
    rows = []
    for index, (key, label) in enumerate([('agentrx', 'AgentRx'), ('agentreroute', 'AgentReroute')]):
        value = metric[key]
        display = f"{value:.{metric['precision']}f}{metric['unit']}"
        count = f" <small>{metric['counts'][index]}</small>" if metric['counts'] else ''
        rows.append(f'''<div class="benchmark-row {key}"><div class="bar-label"><span>{label}{count}</span><strong>{display}</strong></div><div class="bar-track" aria-hidden="true"><span style="--bar:{100 * value / metric['scale']:.6f}%"></span></div></div>''')
    return f'''<figure class="benchmark-chart" data-metric="{metric['id']}"><figcaption><span class="tiny-label">{escape(metric['description'])}</span><h3>{escape(metric['title'])}</h3></figcaption><div class="axis-note"><span>0 — {metric['scale']}{metric['unit']}</span><span>{metric['direction']}</span></div>{''.join(rows)}</figure>'''


def benchmarks():
    panels = []
    for group in ('quality', 'efficiency'):
        datasets = ''.join(f'''<div class="benchmark-dataset" data-backend="{backend}" {'hidden' if backend != 'local' else ''}>{''.join(chart(m) for m in groups[group])}</div>''' for backend, groups in BENCHMARKS.items())
        panels.append(f'''<div id="benchmark-{group}" class="benchmark-panels reveal" {'hidden' if group != 'quality' else ''}>{datasets}</div>''')
    options = ''.join(f'<option value="{key}">{escape(info["label"])}</option>' for key, info in BACKENDS.items())
    notes = ''.join(f'''<p data-backend="{key}" {'hidden' if key != 'local' else ''}><strong>{escape(info['provider'])} · {escape(info['model'])}</strong>{escape(info['note'])}</p>''' for key, info in BACKENDS.items())
    tables = []
    for backend, info in BACKENDS.items():
        rows = ''.join('<tr>' + ''.join(f'<{tag}>{escape(cell)}</{tag}>' for tag, cell in zip(('th', 'td', 'td'), row)) + '</tr>' for row in detail_rows(backend))
        tables.append(f'''<div data-backend="{backend}" {'hidden' if backend != 'local' else ''}><div class="benchmark-table-scroll"><table><caption>{escape(info['label'])} · saved test metrics</caption><thead><tr><th>Metric</th><th>AgentRx</th><th>AgentReroute</th></tr></thead><tbody>{rows}</tbody></table></div><a href="{source_url(backend)}" target="_blank" rel="noopener">Inspect this result file ↗</a></div>''')
    return r'''
<section id="benchmark-results" class="benchmark-section"><div class="wrap">
  <div class="benchmark-topline"><p class="overline">The comparison / AgentReroute &amp; AgentRx</p><span class="evidence-badge">Held-out retail benchmark</span></div>
  <div class="research-heading reveal"><h2>Better decisions.<br><span>Measured by what changes.</span></h2><p>Compare the exact fault found, the tasks recovered, and the resources used. Select a model to see where the gains—and tradeoffs—appear.</p></div>
  <div class="benchmark-controls"><label class="benchmark-model-label" for="benchmark-model">Benchmark model<select id="benchmark-model">''' + options + r'''</select></label><p id="benchmark-provenance">35 failed traces + 17 controls · 7 retail failure modes.<br>AgentReroute uses a trained policy; results from the saved test summaries.</p></div>
  <div class="benchmark-toolbar"><div class="benchmark-switch" role="group" aria-label="Benchmark view"><button type="button" data-benchmark="quality" aria-pressed="true">Quality of recovery</button><button type="button" data-benchmark="efficiency" aria-pressed="false">Cost &amp; diagnosis time</button></div></div>
  ''' + ''.join(panels) + '<div class="benchmark-context" aria-live="polite">' + notes + r'''</div>
  <details class="benchmark-methodology"><summary>More metrics, sources &amp; measurement scope</summary>
  ''' + ''.join(tables) + r'''
  <p>Recovery rates are measured on 35 failed retail traces; control rates use 17 clean/tolerated traces. The policy was trained before this held-out evaluation. These are controlled benchmark findings, not a general accuracy claim.</p>
  <p>The replay-token ratio is recovery tokens divided by original-run tokens, averaged across failed cases. It excludes diagnostic inference and is not an API billing measure. Tokens per recovered case divide all failed-case recovery tokens by the number recovered. Diagnosis latency measures attribution, not total task-completion time.</p>
  <p><strong>Source reconciliation:</strong> the report and saved local summary disagree on AgentReroute efficiency. The JSON records 14,295.8 tokens per recovered case and 3 budget breaches; the report lists 8,187 and 0. Charts and calculations follow the saved JSON, using unrounded inputs.</p>
  <p><a href="''' + REPORT_URL + r'''" target="_blank" rel="noopener">Read the evaluation report ↗</a> · Sources pinned to the same mp_rl revision.</p>
  </details>
  <p class="benchmark-footnote">These results use Qwen or MiniMax with a trained policy. The live Gemini comparison below starts from initial policy weights and produces a separate experiment.</p>
  <a class="text-link research-cta" href="#compare-engines">Now inspect an actual execution <span>↓</span></a>
</div></section>
'''


def impact():
    return r'''
<section id="impact" class="impact-section"><div class="wrap">
  <p class="overline">Beyond the demo / Why this matters</p>
  <h2 class="reveal">Catch the mistake earlier.<br><span>Keep the useful work.</span></h2>
  <p class="impact-intro">In a long agent workflow, one wrong decision can send many later steps in the wrong direction. Locate that decision, keep the valid work before it, and give the team a better way forward.</p>
  <div class="work-preservation reveal"><div class="work-heading"><h3>A correction can be smaller than a restart.</h3><span class="tiny-label">CONCEPTUAL EXAMPLE</span></div><div class="work-row"><span>Restart the task</span><div class="work-track restart" aria-label="All twelve illustrative steps repeated">''' + '<i></i>' * 12 + r'''</div><small>Repeat the whole path</small></div><div class="work-row"><span>Target the fault</span><div class="work-track targeted" aria-label="Keep eight illustrative valid steps and replay four steps">''' + '<i class="kept"></i>' * 8 + '<i class="replayed"></i>' * 4 + r'''</div><small>Keep progress. Replay from here.</small></div><div class="work-legend"><span>● Existing valid work</span><span>● Work to replay</span></div></div>
  <div class="impact-targets"><div class="target-caption"><span class="evidence-badge">Measured in the benchmark</span><h3>Same recovery rate.<br> Two measured gains.</h3><p>Hosted MiniMax comparison.<br>Both methods recovered 25 of 35 failed cases.</p></div>
  <article class="impact-stat"><span class="tiny-label">HOSTED / RECOVERY COST</span><strong>''' + str(IMPACT['cost']) + r'''<span>%</span></strong><h3>Lower replay-token ratio</h3><p>From 1.19× to 0.82× the original-run tokens. A recovery-cost proxy, excluding diagnosis.</p></article>
  <article class="impact-stat"><span class="tiny-label">HOSTED / DIAGNOSIS TIME</span><strong>''' + str(IMPACT['time']) + r'''<span>%</span></strong><h3>Lower mean diagnosis time</h3><p>From 101.83s to 80.27s to attribute the fault. This measures diagnosis, not task completion.</p></article></div>
  <p class="impact-caveat">Relative reductions calculated from the saved hosted results. The local-model tradeoff is different: diagnosis takes longer while recovery improves. These figures do not measure API-bill savings or end-to-end speedup.</p>
  <div class="method-heading"><h3>Different safeguards.<br>Different jobs.</h3><p>A modern agent system can use all three.</p></div>
  <div class="method-cards"><article><span class="tiny-label">BEFORE AN ACTION</span><h4>Validate the tool call.</h4><p>Check arguments, permissions and prerequisites. Useful for invalid operations; a valid call can still serve the wrong goal.</p></article><article><span class="tiny-label">AFTER A FAILURE</span><h4>Retry or restart.</h4><p>Useful for a temporary error or an unrecoverable state. Repeating the same routing choice may repeat the same mistake.</p></article><article class="method-highlight"><span class="tiny-label">AT THE DECISION</span><h4>Locate, correct, replay.</h4><p>Find the earlier choice, apply a targeted repair and verify what changed. Diagnosis adds work; the benefit depends on the rework avoided.</p></article></div>
  <div class="impact-closing"><p>For customer operations, research teams and coding agents:<br><strong>make recovery part of the workflow.</strong></p><a class="pill-link" href="#live-system">Explore the system <span>↑</span></a></div>
</div></section>
'''

