JS = r'''
 const stageButtons=[...document.querySelectorAll('[data-story-stage]')];
 let manualStage=false;
 function selectStage(index){
  visual.dataset.stage=index;
  beats.forEach((b,i)=>b.classList.toggle('active',i===index));
  stageButtons.forEach((b,i)=>b.setAttribute('aria-pressed',String(i===index)));
 }
 stageButtons.forEach(button=>button.addEventListener('click',()=>{manualStage=true;selectStage(Number(button.dataset.storyStage));}));
 function releaseStage(){manualStage=false;queueScroll();}
 addEventListener('wheel',releaseStage,{passive:true});
 addEventListener('touchmove',releaseStage,{passive:true});
 addEventListener('pointerdown',e=>{if(!e.target.closest?.('.story-state-controls'))releaseStage();});
 addEventListener('keydown',e=>{if(['ArrowDown','ArrowUp','PageDown','PageUp','Home','End',' '].includes(e.key))releaseStage();});
 document.querySelectorAll('a[href^="#"]').forEach(a=>a.addEventListener('click',releaseStage));
 document.getElementById('benchmark-model').addEventListener('change',e=>{
  document.querySelectorAll('#benchmark-results [data-backend]').forEach(el=>el.hidden=el.dataset.backend!==e.target.value);
  queueScroll();
 });
 document.querySelectorAll('[data-benchmark]').forEach(button=>button.addEventListener('click',()=>{
  const selected=button.dataset.benchmark;
  document.querySelectorAll('[data-benchmark]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));
  document.querySelectorAll('.benchmark-panels').forEach(panel=>panel.hidden=panel.id!=='benchmark-'+selected);
  queueScroll();
 }));
'''
